import{bV as e,aL as n,u as a,G as l}from"./chunks/framework.BfzMay2U.js";const y=JSON.parse('{"title":"二进制和十进制的转换","description":"","frontmatter":{"title":"二进制和十进制的转换","date":"2026-08-29T13:36:10.000Z"},"headers":[],"relativePath":"java/binary2decimal.md","filePath":"java/binary2decimal.md"}'),r={name:"java/binary2decimal.md"};function s(d,t,i,c,p,x){return n(),a("div",null,[...t[0]||(t[0]=[l(`<h1 id="进制转换" tabindex="-1">进制转换 <a class="header-anchor" href="#进制转换" aria-label="Permalink to &quot;进制转换&quot;">​</a></h1><p>在线禁止转换的工具：<a href="https://tool.lu/hexconvert" target="_blank" rel="noreferrer">https://tool.lu/hexconvert</a></p><p>二进制和十进制数的对应</p><table tabindex="0"><thead><tr><th style="text-align:center;">十进制数</th><th style="text-align:center;">二进制</th><th style="text-align:center;">十六进制</th></tr></thead><tbody><tr><td style="text-align:center;">0</td><td style="text-align:center;">0</td><td style="text-align:center;">0</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">1</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">10</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">11</td><td style="text-align:center;">3</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">100</td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">101</td><td style="text-align:center;">5</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">110</td><td style="text-align:center;">6</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">111</td><td style="text-align:center;">7</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">1000</td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">1001</td><td style="text-align:center;">9</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:center;">1010</td><td style="text-align:center;">a</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:center;">1011</td><td style="text-align:center;">b</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:center;">1100</td><td style="text-align:center;">c</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:center;">1101</td><td style="text-align:center;">d</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:center;">1110</td><td style="text-align:center;">e</td></tr><tr><td style="text-align:center;">15</td><td style="text-align:center;">1111</td><td style="text-align:center;">f</td></tr></tbody></table><h2 id="十进制转二进制" tabindex="-1">十进制转二进制 <a class="header-anchor" href="#十进制转二进制" aria-label="Permalink to &quot;十进制转二进制&quot;">​</a></h2><p>十进制转二进制整数采用“除2取余，逆序排列”法</p><p>比如：十进制 29</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>29/2=14...1</span></span>
<span class="line"><span>14/2=7...0</span></span>
<span class="line"><span>7/2=3...1</span></span>
<span class="line"><span>3/2=1...1</span></span>
<span class="line"><span>1/2=0...1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>然后余数逆序排列：11101，即 29 对应的二进制数是 11101</p><h2 id="二进制转十进制" tabindex="-1">二进制转十进制 <a class="header-anchor" href="#二进制转十进制" aria-label="Permalink to &quot;二进制转十进制&quot;">​</a></h2><p>采用“权相加法”</p><p>比如：二进制数 1011010</p><p>这个二进制数有 6 位</p><p>即 $$ 1<em>2^6+0</em>2^5+1<em>2^4+1</em>2^3+0<em>2^2+1</em>2^1+0*2^0=64+16+8+2=90 $$</p>`,14)])])}const o=e(r,[["render",s]]);export{y as __pageData,o as default};
